I will read cached values from the active sheet and, for each row 4–75, use R/S/T as the three criteria (falling back to N/O/P only if R/S/T are blank). I will sum the C4:M75 cells whose row matches A/B and whose column header in C3:M3 matches the third criterion. I will write the resulting plain numbers into U4:U75 and save the workbook.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
try:
    vws = vals[ws.title]
except KeyError:
    vws = vals.active

def norm(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def eq(a, b):
    a = norm(a)
    b = norm(b)

    if a is None and b is None:
        return True
    if a is None or b is None:
        return False

    if isinstance(a, str) and isinstance(b, str):
        return a.casefold() == b.casefold()

    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b

    try:
        return float(a) == float(b)
    except Exception:
        return False

def to_num(v):
    if v is None:
        return 0
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return 0
        try:
            return float(s)
        except Exception:
            return 0
    return 0

def get_crit(row, primary_col, fallback_col):
    v = vws.cell(row=row, column=primary_col).value
    if v is None or (isinstance(v, str) and not v.strip()):
        v = vws.cell(row=row, column=fallback_col).value
    return norm(v)

results = []

for r in range(4, 76):
    crit_a = get_crit(r, 18, 14)  # R, fallback N
    crit_b = get_crit(r, 19, 15)  # S, fallback O
    crit_h = get_crit(r, 20, 16)  # T, fallback P

    total = 0

    for i in range(4, 76):
        a = vws.cell(row=i, column=1).value
        b = vws.cell(row=i, column=2).value

        if not eq(a, crit_a) or not eq(b, crit_b):
            continue

        for j in range(3, 14):  # C through M
            header = vws.cell(row=3, column=j).value
            if eq(header, crit_h):
                total += to_num(vws.cell(row=i, column=j).value)

    if isinstance(total, float) and total.is_integer():
        total = int(total)

    ws.cell(row=r, column=21).value = total
    results.append(total)

print("rows:", len(results), "first:", results[:5], "last:", results[-5:])
wb.save(OUT)
